from pathlib import Path
p=Path(__file__).parent/'dist/security-head.js'
try:
    s=p.read_text(encoding='utf-8')
except UnicodeDecodeError:
    s=p.read_text(encoding='cp1252')
s=s.replace('Local LLM available','LLM available').replace('Use local LLM','Use selected LLM').replace('Local LLM ordered briefing','LLM ordered briefing').replace("useAI?'Local LLM '","useAI?'LLM '")
s=s.replace('<summary>Free local AI connection</summary>', '''<summary>Mistral online API + local backup</summary><p class="hint">Mistral needs your own Free-mode key. Do not upgrade billing. The server cannot verify your billing plan. Search sends the question and date; briefing sends aggregate counts. Full visitor records, images and phone numbers are not sent automatically. Avoid personal details in online queries.</p><form id="head-mistral-config"><label class="field">Mistral API key<input id="head-mistral-key" type="password" autocomplete="off" maxlength="256" required placeholder="Enter your Free-mode API key"></label><label class="check"><input id="head-free-mode" type="checkbox" required>I confirm my Mistral account is in Free mode</label><div class="actions"><button class="btn">Connect Mistral</button><button class="btn secondary" type="button" id="head-mistral-disconnect">Disconnect Mistral</button><a href="https://console.mistral.ai/" target="_blank" rel="noopener">Create a free key</a></div><p class="hint">Key is held only in server memory, cleared on restart, and never saved in browser storage. A key being configured is not proof of a working connection: run Test AI live.</p></form>''')
s=s.replace('Installed model<select','Selected model<select').replace('Running real local model inference','Running real model inference').replace('Local model connection available. Select Use selected LLM to enable.','Model configured. Run Test AI live to verify the provider.').replace('Ollama is not running or has no installed models. Rule-based tools remain available.','Enter a Mistral key or start a local model. Rule-based tools remain available.').replace('Local AI server unavailable.','AI adapter unavailable.')
anchor=" on('head-ai-check',async()=>"
assert anchor in s
s=s.replace(anchor,""" const config=document.querySelector('#head-mistral-config');if(config)config.onsubmit=async e=>{e.preventDefault();const button=config.querySelector('button');button.disabled=true;try{const input=document.querySelector('#head-mistral-key');const r=await fetch('/api/ai/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:input.value.trim(),freeMode:document.querySelector('#head-free-mode').checked})});input.value='';const result=await r.json();if(!r.ok)throw Error(result.error);headProof='Mistral key configured. Live verification pending.';document.querySelector('#head-ai-proof').textContent=headProof;document.querySelector('#head-ai-check').click();toast(result.message)}catch(err){toast(err.message)}finally{button.disabled=false}};
 on('head-mistral-disconnect',async()=>{try{const r=await fetch('/api/ai/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:''})});if(!r.ok)throw Error('Disconnect failed');headProof='Mistral disconnected.';headAI=false;document.querySelector('#head-ai-proof').textContent=headProof;document.querySelector('#head-ai-check').click()}catch(err){toast(err.message)}});
"""+anchor)
p.write_text(s,encoding='utf-8')
p=Path(__file__).parent/'dist/tech-journey.html'
s=p.read_text(encoding='utf-8').replace('local Ollama adapter','Mistral API adapter + local backup').replace('A local LLM translates','A connected LLM translates').replace('local Ollama adapter','Mistral API adapter').replace('LLM use depends on a running local model.','Mistral use requires a Free-mode API key and a successful live test.').replace('Our local LLM adapter','Our Mistral API adapter')
p.write_text(s,encoding='utf-8')
